//! The `core` dispatcher — hosted plan §3.2 and §10 P2
//! (`docs/tabtivity_hosted_plan.md`).
//!
//! A server host (the Mobile sidecar in P2, the per-user daemon in P3) receives
//! `{cmd, args}` frames from a browser and answers them by calling the same
//! command bodies the desktop registers with Tauri — as plain functions, with a
//! [`CoreCtx`] whose caller is that client. The per-command wrappers are
//! **generated by `build.rs`** from the signatures in `src/commands/*.rs`
//! (`core_dispatch.rs` in `OUT_DIR`, included below): every `#[tauri::command]`
//! whose parameters are a [`crate::tauri_host::Ctx`] and JSON values gets one;
//! a command still taking `State`, `AppHandle`, `Window` or a raw IPC body is in
//! [`NOT_DISPATCHABLE`] with the reason, and `server_capabilities` hides it.
//!
//! Order of checks, by design (P0 handoff): the **class** first — an unknown
//! name, a `client`, `admin` (for a user) or `off` command is refused before any
//! argument is looked at — then whether a wrapper exists, then the arguments,
//! read by the camelCase keys Tauri uses and reported with Tauri's own wording
//! (``invalid args `key` for command `cmd`: …``). The server-side model
//! allowlist (`services::model_allowlist`) runs between the class check and the
//! call for the commands that reach the shared Ollama, and then, for a
//! [`Role::User`], the path confinement: every path-named argument of every
//! `core` command is classified in one table (`USER_CONFINED`) and held to the
//! user's roots (`commands::fs::user_roots`) before the body runs — a project
//! folder, an absolute path, a project's `project.json` — or is named as
//! confined by its body, remote, refused or not a path. A test fails when a
//! command grows a path-named argument the table does not classify.
//!
//! Nothing here knows a WebSocket or a window: the transport hands in a
//! `CoreCtx` built for the caller and gets JSON back.

use std::future::Future;
use std::pin::Pin;

use app_core::CoreCtx;
use serde::de::DeserializeOwned;
use serde::Serialize;
use serde_json::Value;

use crate::services::command_class::{self, CommandClass};

/// What a wrapper answers: the command's `Ok` as JSON, or its error as JSON (a
/// string for the usual `Result<T, String>`, Tauri's `InvokeError` shape).
pub type BoxFuture = Pin<Box<dyn Future<Output = Result<Value, Value>> + Send>>;
/// One generated wrapper.
pub type Handler = fn(CoreCtx, Value) -> BoxFuture;

/// The generated wrappers. Machine-written, so the style lints a hand would
/// satisfy (a closure around a bare call) are allowed here and nowhere else.
#[allow(clippy::redundant_closure, clippy::let_unit_value, clippy::unit_arg, clippy::vec_init_then_push)]
mod generated {
    use super::*;
    include!(concat!(env!("OUT_DIR"), "/core_dispatch.rs"));
}
pub use generated::{dispatchable_names, handler, NOT_DISPATCHABLE};

/// Read one argument the way `#[tauri::command]` does: by key, a missing key
/// deserializing as `null` (so an `Option` is `None` and anything else fails),
/// with Tauri's own error wording.
fn arg<T: DeserializeOwned>(args: &Value, key: &str, cmd: &str) -> Result<T, Value> {
    T::deserialize(args.get(key).unwrap_or(&Value::Null))
        .map_err(|e| Value::String(format!("invalid args `{key}` for command `{cmd}`: {e}")))
}

fn to_json<T: Serialize>(value: T) -> Result<Value, Value> {
    serde_json::to_value(value).map_err(|e| Value::String(format!("serialize answer: {e}")))
}

fn result_to_json<T: Serialize, E: Serialize>(out: Result<T, E>) -> Result<Value, Value> {
    match out {
        Ok(v) => to_json(v),
        Err(e) => Err(serde_json::to_value(e).unwrap_or_else(|e| Value::String(format!("serialize error: {e}")))),
    }
}

/// Run a sync command body on the blocking pool (Tauri keeps sync commands off
/// its async runtime too). A panic in the body is an error answer, not a dead
/// connection.
async fn blocking<T: Send + 'static>(body: impl FnOnce() -> T + Send + 'static) -> Result<T, Value> {
    app_core::rt::spawn_blocking(body)
        .await
        .map_err(|e| Value::String(format!("command failed: {e}")))
}

/// Who the caller is to the server as a whole (plan §3.3 `admin`). The
/// single-user sidecar's token login is the box's admin; on a multi-user
/// server the gateway names the account's role in the connection's handshake
/// (`services::server`), and the daemon passes it in here per call — and into
/// the call's `CoreCtx` (`with_client`), so a body can ask
/// `is_untrusted_client`. Defined in the core, which the context lives in.
pub use app_core::Role;

/// Why a command is not served, as the frontend sees it (`server_capabilities`
/// rows and the error of a refused call). Wire shape `{code, reason?}`.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(tag = "code", rename_all = "kebab-case")]
pub enum Refusal {
    /// No registered command of that name.
    Unknown,
    /// Runs on the machine the user sits at; the browser adapts or hides it.
    Client,
    /// Admin role only.
    Admin,
    /// Nothing in server mode can do it (`command_class::OffReason` token).
    Off { reason: &'static str },
    /// Classed `core` but its body still needs Tauri (`NOT_DISPATCHABLE`).
    Unsupported { reason: &'static str },
    /// A server feature (mail, calendar, todo) the admin or the user switched
    /// off (hosted plan §6.7); its data stays.
    FeatureOff { feature: &'static str },
}

/// The class check alone: unknown, `client`, `off`, or `admin` for a user.
/// What a transport answering a command itself (`read_file_bytes` as a
/// binary frame) must run before touching the frame — the wrapper table does
/// not apply to it, the class table always does.
pub fn class_refusal(cmd: &str, role: Role) -> Option<Refusal> {
    match command_class::class_of(cmd) {
        None => Some(Refusal::Unknown),
        Some(CommandClass::Client) => Some(Refusal::Client),
        Some(CommandClass::Off(reason)) => Some(Refusal::Off { reason: reason.as_str() }),
        Some(CommandClass::Admin) if role != Role::Admin => Some(Refusal::Admin),
        Some(CommandClass::Admin) | Some(CommandClass::Core) => None,
    }
}

/// Whether `cmd` is served for `role`, or why not. The class decides first;
/// the generated table second; arguments never (they are the call's business).
pub fn refusal(cmd: &str, role: Role) -> Option<Refusal> {
    if let Some(refused) = class_refusal(cmd, role) {
        return Some(refused);
    }
    if let Some(feature) = crate::services::server::feature_refusal(cmd) {
        return Some(Refusal::FeatureOff { feature: feature.as_str() });
    }
    if handler(cmd).is_some() {
        return None;
    }
    let reason = NOT_DISPATCHABLE
        .iter()
        .find(|(name, _)| *name == cmd)
        .map(|(_, reason)| *reason)
        .unwrap_or("no wrapper was generated for it");
    Some(Refusal::Unsupported { reason })
}

/// Is `cmd` served for `role`?
pub fn served(cmd: &str, role: Role) -> bool {
    refusal(cmd, role).is_none()
}

/// Call `cmd` with `args` (the JSON object the frontend's `invoke` sent) for
/// the client `ctx.caller` names. A refusal is an `Err` carrying the
/// [`Refusal`]'s JSON, so the frontend can tell "not served here" from a
/// command's own error.
pub async fn dispatch(ctx: &CoreCtx, role: Role, cmd: &str, mut args: Value) -> Result<Value, Value> {
    if let Some(refusal) = refusal(cmd, role) {
        return Err(serde_json::to_value(refusal).unwrap_or(Value::Null));
    }
    crate::services::model_allowlist::check_off_thread(cmd, &args).await?;
    confine_for_user(role, cmd, &mut args)?;
    let run = handler(cmd).expect("refusal() checked the wrapper exists");
    run(ctx.clone(), args).await
}

/// How [`confine_for_user`] holds one path-named argument of a `core`
/// command for a [`Role::User`] (hosted plan §6; the screen's fixed decision
/// #6). An admin is never held: the box is theirs.
///
/// Defence in depth, not the uid boundary: a user's daemon runs under their
/// own uid and serves them unfenced shell tabs (`pty_spawn` is `core`). What
/// it buys is consistency — no file command reaches past the user's projects
/// because a path argument was trusted.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Kind {
    /// The server-side folder picker's start (`list_dir_all`, `list_dirs`):
    /// empty is the root work dir, anything else is held like [`Kind::UserPath`].
    Picker,
    /// An absolute local path, held to the user's roots (`fs::user_roots`).
    /// Empty or relative is refused; absent (`null`) is left to the body.
    UserPath,
    /// [`Kind::UserPath`] for an `Option` argument whose body reads empty as
    /// absent: an empty value becomes `null`.
    UserPathOpt,
    /// An output folder (`compile_tex.outDir`): a relative value is taken
    /// against the folder of the named sibling path, as the body does, and
    /// the result held like [`Kind::UserPath`]; empty is absent.
    OutDirOf(&'static str),
    /// An optional path the body only looks near (the formatter's config and
    /// `node_modules` beside a file): one outside the user's roots — a remote
    /// file's host path, say — becomes `null`, as if none was given, instead
    /// of failing the call.
    Hint,
    /// A path on the host when the named sibling (a `projectId`) is a remote
    /// project's — the body then walks it over SSH — else held like
    /// [`Kind::UserPath`].
    LocalUnlessRemote(&'static str),
    /// A new or imported project's own folder. Held like [`Kind::UserPath`]
    /// unless the request names a remote site (a non-null `remote`) — then
    /// the body ignores it and keeps the project in the server's state dir.
    /// Without this a user could register `/` as a project and widen their
    /// own roots. Only what the request type itself honours lets the folder
    /// through: a key the body's type does not have (`vm` on an import) is
    /// dropped by serde, and the folder is used after all.
    LocalSite,
    /// [`Kind::LocalSite`] for `create_project`, whose request also honours
    /// `vm.enabled` (a VM project is a remote one; the body synthesizes its
    /// `remote`).
    LocalSiteOrVm,
    /// [`Kind::LocalFile`] where the body reads empty as "no project file"
    /// (`workspace_sync` of the root or a box scope): empty passes, as empty.
    LocalFileOpt,
    /// A `SkillTarget` (`{kind: "project", dir}` / `{kind: "personal"}`): a
    /// project's `dir` is held like [`Kind::UserPath`]; the personal target —
    /// the real home's `~/.claude/skills`, outside every root and seen by no
    /// agent tab (they run in Tabtivity's agent homes) — is refused.
    SkillTarget,
    /// A list of folders the body only looks inside (`resolve_text_paths`'s
    /// `bases`): each one outside the user's roots is dropped from the list.
    HintEach,
    /// A `GitWorktreeSelection` (`{path, site}`) beside the named
    /// `projectDir`: its `path` is where git then runs. On a remote project's
    /// host side it is a host path; anywhere else it is held like
    /// [`Kind::UserPath`] — the body accepts any checkout the repository's own
    /// worktree list names, and that list is files in the user's project.
    WorktreeOf(&'static str),
    /// A project folder the body then confines a relative path within
    /// (`fs::enforce_confinement`): the folder itself is held to the user's
    /// roots, or `"/"` would make every relative path a whole-disk one.
    ProjectDir,
    /// A project's `project.json`: must be a known project's `local_file`.
    LocalFile,
    /// The body confines it already (`open_confined`, `confine_abs_read`,
    /// `confine_project_path`, `sqlite::confine`, `enforce_confinement`
    /// within a held [`Kind::ProjectDir`], a worktree root) or never touches
    /// the filesystem with it. Listed so the coverage test knows it was looked at.
    BodyConfined,
    /// A path on an SSH/HPC host or in a remote project's tree, resolved from
    /// the project: not this server's filesystem. Governed by the host
    /// allow-list, not by roots.
    Remote,
    /// Not served to a user at all.
    Refuse,
    /// Not a filesystem path; the key only looks like one (a mail folder id,
    /// a CalDAV href, a git ref, a flag, a catalog path).
    NotAPath,
}

