    fn path_named(key: &str) -> bool {
        let key = key.to_ascii_lowercase();
        PATH_NAMED.iter().any(|word| key.contains(word))
    }

    /// Every argument of a dispatchable `core` command whose key reads like a
    /// path has a `USER_CONFINED` row (a struct argument counts as classified
    /// when a row names a field of it), and every row names a real command
    /// and, where the build has its wrapper, one of its argument keys.
    #[test]
    fn every_path_named_core_argument_is_classified() {
        let mut missing = Vec::new();
        for name in dispatchable_names() {
            if command_class::class_of(name) != Some(CommandClass::Core) {
                continue;
            }
            for key in super::generated::arg_keys(name).unwrap_or(&[]) {
                let covered = USER_CONFINED.iter().any(|(cmd, row, _)| {
                    *cmd == name && (*row == *key || row.strip_prefix(*key).is_some_and(|rest| rest.starts_with('.')))
                });
                if path_named(key) && !covered {
                    missing.push(format!("{name}.{key}"));
                }
            }
        }
        assert!(missing.is_empty(), "path-named arguments with no confinement row (classify each in USER_CONFINED):\n{}", missing.join("\n"));
        let mut stale = Vec::new();
        let mut seen = std::collections::HashSet::new();
        for (cmd, key, _) in USER_CONFINED {
            if !seen.insert((cmd, key)) {
                stale.push(format!("{cmd}.{key} (twice)"));
            }
            if command_class::class_of(cmd) != Some(CommandClass::Core) {
                stale.push(format!("{cmd}.{key} (not a core command)"));
            }
            let head = key.split('.').next().unwrap_or(key);
            if let Some(keys) = super::generated::arg_keys(cmd) {
                if !keys.contains(&head) {
                    stale.push(format!("{cmd}.{key} (no such argument)"));
                }
            }
        }
        assert!(stale.is_empty(), "stale USER_CONFINED rows:\n{}", stale.join("\n"));
    }

    #[test]
    fn the_class_is_checked_before_anything_else() {
        assert_eq!(refusal("no_such_command", Role::Admin), Some(Refusal::Unknown));
        assert_eq!(refusal("clipboard_has_image", Role::Admin), Some(Refusal::Client));
        assert_eq!(refusal("save_settings", Role::Admin), Some(Refusal::Off { reason: "whole-document-save" }));
        assert_eq!(refusal("install_ollama", Role::User), Some(Refusal::Admin));
        assert_eq!(refusal("install_ollama", Role::Admin), None);
        assert_eq!(refusal("pty_write", Role::User), None);
        assert!(matches!(refusal("read_file_bytes", Role::User), Some(Refusal::Unsupported { .. })));
    }

    #[tokio::test]
    async fn a_refused_call_never_reaches_a_body() {
        let err = dispatch(&ctx(), Role::User, "clipboard_has_image", serde_json::json!({})).await.unwrap_err();
        assert_eq!(err["code"], "client");
        let err = dispatch(&ctx(), Role::User, "nope", Value::Null).await.unwrap_err();
        assert_eq!(err["code"], "unknown");
        let err = dispatch(&ctx(), Role::User, "save_boxes", Value::Null).await.unwrap_err();
        assert_eq!(err, serde_json::json!({ "code": "off", "reason": "whole-document-save" }));
    }

    #[tokio::test]
    async fn arguments_are_read_by_camel_case_key_and_reported_like_tauri() {
        // `agent_is_installed(id: String)` reads nothing but `PATH`.
        let err = dispatch(&ctx(), Role::User, "agent_is_installed", serde_json::json!({})).await.unwrap_err();
        assert_eq!(err, Value::String("invalid args `id` for command `agent_is_installed`: invalid type: null, expected a string".into()));
        let ok = dispatch(&ctx(), Role::User, "agent_is_installed", serde_json::json!({ "id": "no-such-cli-xyz" })).await.unwrap();
        assert_eq!(ok, Value::Bool(false));
    }

