    async fn a_plain_return_and_a_unit_return_answer_json() {
        // `ollama_is_installed() -> bool` (a `PATH` probe).
        let out = dispatch(&ctx(), Role::User, "ollama_is_installed", Value::Null).await.unwrap();
        assert!(out.is_boolean());
    }

    #[test]
    fn capabilities_cover_every_row_and_carry_the_host() {
        let caps = capabilities(Role::User, 1);
        assert_eq!(caps.commands.len(), command_class::all().len());
        assert_eq!(caps.host_os, host_os());
        let served = caps.commands.iter().filter(|c| c.served).count();
        assert!(served > 450, "{served} served");
        let off = caps.commands.iter().find(|c| c.name == "keyring_unlock").unwrap();
        assert_eq!(off.class, "off");
        assert_eq!(off.refusal, Some(Refusal::Off { reason: "os-keychain" }));
        let admin = caps.commands.iter().find(|c| c.name == "pull_ollama_model").unwrap();
        assert!(!admin.served);
        assert!(capabilities(Role::Admin, 1).commands.iter().find(|c| c.name == "pull_ollama_model").unwrap().served);
        let json = serde_json::to_value(&caps).unwrap();
        assert!(json["commands"][0]["refusal"].is_null() || json["commands"][0]["refusal"]["code"].is_string());
    }

    #[test]
    fn camel_keys_match_tauri() {
        // The generator's rule is exercised through a generated wrapper: a
        // snake_case parameter is read under its camelCase key only.
        let rt = tokio::runtime::Runtime::new().unwrap();
        let err = rt
            .block_on(dispatch(&ctx(), Role::User, "agent_prompt_blame", serde_json::json!({ "project_id": "x" })))
            .unwrap_err();
        assert!(err.as_str().unwrap().starts_with("invalid args `projectId` for command `agent_prompt_blame`"), "{err}");
    }
